/**
 * Test flow for Remote Table Query trigger
 * Tests: Remote table query trigger with query parameters
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testRemoteTableQueryTrigger = Flow(
    {
        $id: Now.ID['test_remote_table_query_trigger_flow'],
        name: 'Test Remote Table Query Trigger',
        description: 'Tests the Remote Table Query trigger for virtual tables',
    },
    wfa.trigger(
        trigger.application.remoteTableQuery,
        { $id: Now.ID['test_remote_table_query_trigger'] },
        {
            u_table: 'sc_cat_item',
        }
    ),
    (_params) => {
        // Log remote table query details
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['test_remote_table_query_log'],
            },
            {
                log_level: 'info',
                log_message: `Remote Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Query ID: ${wfa.dataPill(_params.trigger.query_id, 'string')}, Query Parameters: ${wfa.dataPill(_params.trigger.query_parameters, 'string')}`,
            }
        )
    }
)
